#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

spec fn is_lowercase(c: char) -> bool {
    c >= 'a' && c <= 'z'
}

spec fn all_lowercase(v: Seq<char>) -> bool {
    v.len() > 0 && (forall|i: int| 0 <= i < v.len() ==> is_lowercase(v[i]))
}

fn check_all_lowercase(v: &Vec<char>) -> (res: bool)
    ensures
        res == all_lowercase(v@),
{
    if v.len() == 0 {
        return false;
    }
    let mut i: usize = 0;
    while i < v.len()
        invariant
            v.len() > 0,
            i <= v.len(),
            // Everything before i has been checked to be lowercase
            forall|j: int| 0 <= j < i as int ==> is_lowercase(v@[j]),
    {
        let c = v[i];
        if !(c >= 'a' && c <= 'z') {
            // Show: not all_lowercase(v@)
            assert(!is_lowercase(v@[i as int]));
            assert(!(forall|k: int| 0 <= k < v@.len() ==> is_lowercase(v@[k])));
            assert(!all_lowercase(v@));
            return false;
        }
        i += 1;
    }
    // Completed scan; v.len()>0 and all chars are lowercase
    assert(forall|k: int| 0 <= k < v@.len() ==> is_lowercase(v@[k]));
    assert(all_lowercase(v@));
    true
}

fn solve(input: Vec<char>) -> (out: Vec<char>)
    ensures
        // output is exactly one of ['a'] or ['A']
        out@ == seq!['a'] || out@ == seq!['A'],
        // iff input is all lowercase, output is ['a']
        (all_lowercase(input@) <==> out@ == seq!['a']),
        // otherwise output is ['A']
        (!all_lowercase(input@) <==> out@ == seq!['A']),
{
    if check_all_lowercase(&input) {
        let out = vec!['a'];
        proof {
            assert(out@ == seq!['a']);
            assert(out@ == seq!['a'] || out@ == seq!['A']);
            assert(all_lowercase(input@)); // from check_all_lowercase ensures and branch condition
        }
        out
    } else {
        let out = vec!['A'];
        proof {
            assert(out@ == seq!['A']);
            assert(out@ == seq!['a'] || out@ == seq!['A']);
            assert(!all_lowercase(input@)); // from check_all_lowercase ensures and branch condition
        }
        out
    }
}

} // verus!